const canvas=document.getElementById('arena'),ctx=canvas.getContext('2d');
const W=900,H=610,lanes=[185,425],$=id=>document.getElementById(id);
const cards=[
 {id:'thrall',name:'Crypt Thrall',type:'Undead • Common',cost:2,icon:'🧛',color:'#bc5570',hp:115,damage:23,speed:45,range:25,rate:.9,count:1},
 {id:'wolves',name:'Night Prowlers',type:'Pack • Swarm',cost:3,icon:'🐺',color:'#82a3c7',hp:72,damage:16,speed:66,range:24,rate:.72,count:3},
 {id:'knight',name:'Blood Knight',type:'Vanguard • Rare',cost:4,icon:'🛡️',color:'#dc9d62',hp:310,damage:40,speed:31,range:29,rate:1.15,count:1},
 {id:'dracula',name:'Count Dracula',type:'Legendary • Crownless',cost:5,icon:'🦇',color:'#d783c0',hp:430,damage:56,speed:38,range:105,rate:1.25,count:1},
 {id:'banshee',name:'Sanguine Wail',type:'Blood magic • Spell',cost:3,icon:'🌙',color:'#c48be0',spell:true},
 {id:'lycan',name:'Lycan King',type:'Legendary • Alpha',cost:6,icon:'🐺',color:'#a9c5e9',hp:540,damage:64,speed:39,range:32,rate:1.25,count:1,enemyOnly:true}
];
let hand=[0,1,2,3],cycle=4,selected=-1,elixir=5,timeLeft=120,started=false,paused=false,ended=false,sound=true;
let units=[],shots=[],particles=[],effects=[],towers=[],last=0,aiClock=2.2,toastClock=0;
function makeTower(team,kind,x,y,hp){return{team,kind,x,y,hp,max:hp,alive:true,cool:0}}
function resetGame(){units=[];shots=[];particles=[];effects=[];elixir=5;timeLeft=120;selected=-1;ended=false;paused=false;aiClock=2.2;
 towers=[makeTower('player','king',65,305,1450),makeTower('player','lane',125,185,760),makeTower('player','lane',125,425,760),makeTower('enemy','king',835,305,1450),makeTower('enemy','lane',775,185,760),makeTower('enemy','lane',775,425,760)];
 $('endOverlay').classList.add('hidden');$('pauseBtn').textContent='Ⅱ';renderHand();updateHud();}
function startGame(){resetGame();started=true;$('intro').classList.add('hidden');last=performance.now();requestAnimationFrame(frame);}
function renderHand(){const box=$('hand');box.innerHTML='';hand.forEach((cardIndex,i)=>{const c=cards[cardIndex],button=document.createElement('button');button.className='card'+(selected===i?' selected':'')+(elixir<c.cost?' disabled':'');button.style.setProperty('--accent',c.color);button.innerHTML=`<span class="cost">${c.cost}</span><div class="card-art">${c.icon}</div><div class="card-name">${c.name}</div><div class="card-type">${c.type.split(' • ')[0]}</div>`;button.setAttribute('aria-label',`${c.name}, costs ${c.cost} elixir`);button.onclick=()=>{if(!started||ended||paused)return;if(c.enemyOnly){showToast('The Lycan King answers only to the Frostfangs.');return}if(elixir<c.cost){showToast('Not enough blood elixir.');return}selected=selected===i?-1:i;renderHand();$('battleNote').textContent=selected<0?'Choose a card · summon on your side':`Tap a lane to summon ${c.name}`};box.appendChild(button)});$('nextCard').textContent='NEXT: '+cards[cycle].name.toUpperCase();}
function updateHud(){const secs=Math.ceil(timeLeft),m=Math.floor(secs/60),s=secs%60;$('timer').textContent=`${m}:${String(s).padStart(2,'0')}`;$('manaValue').textContent=elixir.toFixed(1);$('manaFill').style.width=(elixir*10)+'%';renderHand();}
function showToast(message){$('toast').textContent=message;$('toast').classList.add('show');toastClock=2.1}
function beep(freq=360,duration=.08){if(!sound)return;try{const ac=beep.ac||(beep.ac=new(window.AudioContext||window.webkitAudioContext)()),o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch(e){}}
function spawn(card,team,lane,x){if(card.spell){const targetX=team==='player'?Math.min(730,x+220):Math.max(170,x-220);const targetY=lanes[lane];effects.push({x:targetX,y:targetY,t:0,spell:true,team});for(const u of units)if(u.team!==team&&Math.hypot(u.x-targetX,u.y-targetY)<108)u.hp-=95;for(const t of towers)if(t.team!==team&&t.alive&&Math.hypot(t.x-targetX,t.y-targetY)<85)t.hp-=110;for(let i=0;i<18;i++)particles.push({x:targetX+(Math.random()-.5)*95,y:targetY+(Math.random()-.5)*65,vx:(Math.random()-.5)*80,vy:(Math.random()-.5)*80,life:.65,color:'#dca6f5'});beep(180,.2);return}
 for(let n=0;n<card.count;n++){let offset=card.count>1?(n-1)*23:0;units.push({team,card:card.id,x:x+(team==='player'?1:-1)*Math.abs(offset),y:lanes[lane]+offset*.55,lane,hp:card.hp,max:card.hp,damage:card.damage,speed:card.speed,range:card.range,rate:card.rate,cool:Math.random()*.4,radius:card.id==='dracula'?18:card.id==='knight'?15:card.id==='wolves'?9:12,icon:card.id==='dracula'?'🧛‍♂️':card.id==='knight'?'⚔️':card.id==='wolves'?'🐺':'🧛',color:team==='player'?card.color:'#a5b9d1',facing:team==='player'?1:-1,flash:0})}
 for(let i=0;i<7;i++)particles.push({x,y:lanes[lane]+(Math.random()-.5)*22,vx:(Math.random()-.5)*60,vy:-Math.random()*65,life:.55,color:team==='player'?'#d95877':'#a9c6ed'});beep(card.id==='dracula'?220:440,.09)}
function deploy(i,x,y){const card=cards[hand[i]];if(card.enemyOnly)return;if(elixir<card.cost){showToast('Not enough blood elixir.');return}if(x>438){showToast('Summon within your half of the arena.');return}const lane=y<H/2?0:1;elixir-=card.cost;spawn(card,'player',lane,Math.max(225,Math.min(405,x)));hand[i]=cycle;cycle=(cycle+1)%5;selected=-1;renderHand();$('battleNote').textContent='Choose a card · summon on your side';}
canvas.addEventListener('pointerdown',e=>{if(!started||paused||ended)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;if(selected>=0)deploy(selected,x,y)});
function nearestUnit(u){let best=null,dist=Infinity;for(const v of units){if(v.team===u.team||v.hp<=0||Math.abs(v.y-u.y)>72)continue;const d=Math.hypot(v.x-u.x,v.y-u.y);if(d<dist&&d<132){best=v;dist=d}}return best}
function targetTower(u){const enemy=u.team==='player'?'enemy':'player',dir=u.team==='player'?1:-1;const active=towers.filter(t=>t.team===enemy&&t.alive);const laneTower=active.find(t=>t.kind==='lane'&&Math.abs(t.y-u.y)<75);return laneTower||active.find(t=>t.kind==='king')||active[0]}
function damageTower(t,amount){if(!t||!t.alive)return;t.hp-=amount;if(t.hp<=0){t.hp=0;t.alive=false;for(let i=0;i<30;i++)particles.push({x:t.x+(Math.random()-.5)*40,y:t.y+(Math.random()-.5)*45,vx:(Math.random()-.5)*130,vy:(Math.random()-.5)*130,life:1,color:t.team==='enemy'?'#db6782':'#9db6d2'});if(t.kind==='king')finish(t.team==='enemy'?'victory':'defeat');else showToast(t.team==='enemy'?'Enemy guard tower has fallen!':'Your guard tower has fallen!');}}
function finish(result){if(ended)return;ended=true;const win=result==='victory';$('endCrest').textContent=win?'👑':'🌑';$('endTitle').textContent=win?'VICTORY':'THE NIGHT IS LOST';$('endText').textContent=win?'The Frostfang crown is broken. The night belongs to the Vampire Dominion.':'The Lycan King has claimed the arena. Rally your court and fight again.';$('endOverlay').classList.remove('hidden')}

