function finish(result){if(ended)return;ended=true;const win=result==='victory';$('endCrest').textContent=win?'👑':'🌑';$('endTitle').textContent=win?'VICTORY':'THE NIGHT IS LOST';$('endText').textContent=win?'The Frostfang crown is broken. The night belongs to the Vampire Dominion.':'The Lycan King has claimed the arena. Rally your court and fight again.';$('endOverlay').classList.remove('hidden')}
let decor=[];for(let i=0;i<190;i++){const x=Math.random()*W,y=Math.random()*H;if(Math.abs(x-450)>80&&Math.min(Math.abs(y-185),Math.abs(y-425))>48)decor.push({x,y,r:2+Math.random()*9,kind:Math.random()>.45?0:1})}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawArena(){
 const g=ctx.createLinearGradient(0,0,900,610);g.addColorStop(0,'#273b32');g.addColorStop(.48,'#384032');g.addColorStop(1,'#34414a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // shadowed forest edges and battle lanes
 const shade=ctx.createRadialGradient(450,305,120,450,305,520);shade.addColorStop(0,'#53604444');shade.addColorStop(1,'#0b1115a8');ctx.fillStyle=shade;ctx.fillRect(0,0,W,H);
 ctx.fillStyle='#aa936e20';ctx.fillRect(0,132,W,106);ctx.fillRect(0,372,W,106);ctx.fillStyle='#1b1b1b18';ctx.fillRect(0,132,W,2);ctx.fillRect(0,236,W,2);ctx.fillRect(0,372,W,2);ctx.fillRect(0,476,W,2);
 for(const d of decor){ctx.globalAlpha=.4;ctx.fillStyle=d.kind?'#162b26':'#758052';ctx.beginPath();ctx.arc(d.x,d.y,d.r,0,Math.PI*2);ctx.fill();if(d.kind){ctx.fillStyle='#a8a06a';ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(d.x-2,d.y-2,1.3,0,7);ctx.fill()}ctx.globalAlpha=1}
 // river, banks, glimmer
 ctx.fillStyle='#b8a47a';ctx.beginPath();ctx.moveTo(430,0);ctx.bezierCurveTo(447,70,421,120,438,190);ctx.bezierCurveTo(454,262,419,316,441,383);ctx.bezierCurveTo(458,463,421,524,440,610);ctx.lineTo(479,610);ctx.bezierCurveTo(464,528,493,466,473,391);ctx.bezierCurveTo(453,317,488,250,469,183);ctx.bezierCurveTo(450,115,480,63,461,0);ctx.closePath();ctx.fill();
 const rg=ctx.createLinearGradient(432,0,476,0);rg.addColorStop(0,'#384d5a');rg.addColorStop(.45,'#607b84');rg.addColorStop(1,'#354954');ctx.fillStyle=rg;ctx.beginPath();ctx.moveTo(434,0);ctx.bezierCurveTo(451,70,425,120,442,190);ctx.bezierCurveTo(458,262,423,316,445,383);ctx.bezierCurveTo(462,463,425,524,444,610);ctx.lineTo(475,610);ctx.bezierCurveTo(460,528,489,466,469,391);ctx.bezierCurveTo(449,317,484,250,465,183);ctx.bezierCurveTo(446,115,476,63,457,0);ctx.closePath();ctx.fill();
 for(let i=0;i<13;i++){const y=(i*57+18)%610,x=449+Math.sin(i*2.7)*11;ctx.strokeStyle='#c2d5cb33';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+7,y-3,x+14,y);ctx.stroke()}
 // timber bridges across river at both lanes
 lanes.forEach(y=>{ctx.fillStyle='#1d1714';rr(416,y-26,68,52,5);ctx.fill();ctx.fillStyle='#76543c';rr(420,y-22,60,44,3);ctx.fill();for(let x=424;x<479;x+=10){ctx.fillStyle=x%20?'#9b7854':'#886548';ctx.fillRect(x,y-20,7,40);ctx.strokeStyle='#d2a87955';ctx.lineWidth=1;ctx.strokeRect(x,y-19,7,38)}ctx.fillStyle='#d6bf9366';ctx.fillRect(418,y-25,64,3);ctx.fillRect(418,y+22,64,3)});
 // lane labels
 ctx.font='9px DM Sans';ctx.fillStyle='#e7d4a844';ctx.textAlign='center';ctx.fillText('MOONLIT CAUSEWAY',278,150);ctx.fillText('WOLFSBANE TRAIL',620,450);
 // territories softly tinted
 const playerTint=ctx.createLinearGradient(0,0,450,0);playerTint.addColorStop(0,'#6b233320');playerTint.addColorStop(1,'#6b233300');ctx.fillStyle=playerTint;ctx.fillRect(0,0,450,H);const enemyTint=ctx.createLinearGradient(450,0,900,0);enemyTint.addColorStop(0,'#4e5e7b00');enemyTint.addColorStop(1,'#4e5e7b2c');ctx.fillStyle=enemyTint;ctx.fillRect(450,0,450,H);
 // territory boundary and deployment guide
 ctx.save();ctx.setLineDash([5,8]);ctx.strokeStyle='#eee0c522';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(450,22);ctx.lineTo(450,588);ctx.stroke();ctx.restore();
 towers.forEach(drawTower);units.forEach(drawUnit);shots.forEach(drawShot);effects.forEach(drawEffect);particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,2.4,0,7);ctx.fill();ctx.globalAlpha=1});
 // selected-card subtle summon guide
 if(selected>=0&&started&&!paused){ctx.fillStyle='#dba6690b';ctx.fillRect(0,0,438,H);ctx.strokeStyle='#e4bf7766';ctx.setLineDash([4,7]);ctx.beginPath();ctx.moveTo(438,28);ctx.lineTo(438,582);ctx.stroke();ctx.setLineDash([])}
}
